$raw = gemini -p "只使用本段文字，不使用工具。摘要：社群讀書會在青葉中心舉辦，日期未公告。請列出已知資訊與待確認事項。" -o json
$runExitCode = $LASTEXITCODE
if ($runExitCode -ne 0) { throw "Gemini CLI 執行失敗：$runExitCode" }
$result = ($raw -join "`n") | ConvertFrom-Json
if ($result.error -or -not $result.response) { throw "沒有可用回覆" }
$result.response
